function createCatalog(column: 1 | 2 | 3 | 4): ReadonlyMap<string, string> {
  const catalog = new Map(FEATURE_UI_ENTRIES.map(entry => [entry[0].toLocaleLowerCase('en-US'), entry[column]]));
  // Manga renders these two maintained labels as one text node. Compose only
  // the known save-state pairs; arbitrary user text never enters this catalog.
  for (const status of ['Loading draft…', 'Saving draft…', 'Draft ready', 'Draft saved locally', 'Draft save failed', 'Save project manually']) {
    for (const destination of ['Saved to User folder', 'User-folder save pending']) {
      const key = `${status} · ${destination}`.toLocaleLowerCase('en-US');
      catalog.set(key, `${catalog.get(status.toLocaleLowerCase('en-US'))} · ${catalog.get(destination.toLocaleLowerCase('en-US'))}`);
    }
  }
  return catalog;
}
export const FEATURE_UI_TEXT: Record<RecentUiLanguage, ReadonlyMap<string, string>> = {
  ja: createCatalog(1),
  'zh-CN': createCatalog(2),
  ko: createCatalog(3),
  de: createCatalog(4),
};
